import os
import json
import difflib
import csv
import string

# --- CONFIGURATION (Dynamic Relative Paths) ---

# 1. Find the exact folder where this Python script is located
BASE_DIR = os.path.dirname(os.path.abspath(__file__))

# 2. Set Paths (Going UP TWO folder levels to find the main "data" folder)[cite: 5]
# BASE_DIR is currently:  .../Project/ASR_evaluation/alignment_scripts/
# We use "..", ".." to go back to the main "Project" folder.

# INPUT 1: Read JSON transcripts generated by Step 2
DIR_JSON = os.path.join(BASE_DIR, "..", "..", "..", "data", "interim", "transcripts")

# INPUT 2: Read original Gold Standard TXT files
DIR_TXT = os.path.join(BASE_DIR, "..", "..", "..", "data", "raw", "gold_transcripts")

# OUTPUT: Save aligned CSV reports
DIR_OUT = os.path.join(BASE_DIR, "..", "..", "..", "data", "interim", "alignment_reports")


def clean_for_matching(word):
    """
    Removes punctuation and converts to lowercase.
    This ensures that words like "Cookie," and "cookie" match perfectly,
    preventing false errors during the alignment process.[cite: 5]
    """
    return word.translate(str.maketrans('', '', string.punctuation)).lower()


def align_transcripts(json_path, txt_path, out_path):
    """
    Aligns the Whisper JSON output with the Gold Standard TXT.
    Saves the output to a CSV file.[cite: 5]
    """
    # 1. Read Gold Standard TXT
    with open(txt_path, 'r', encoding='utf-8') as f:
        gold_words = f.read().split()

    # 2. Read Whisper JSON
    with open(json_path, 'r', encoding='utf-8') as f:
        whisper_data = json.load(f)

    whisper_words = []
    timestamps = []
    
    for item in whisper_data.get("words", []):
        whisper_words.append(item.get("word", ""))
        timestamps.append((item.get("start", ""), item.get("end", "")))

    # 3. Clean words just for the internal matching algorithm
    gold_cleaned = [clean_for_matching(w) for w in gold_words]
    whisper_cleaned = [clean_for_matching(w) for w in whisper_words]

    # 4. Perform alignment using SequenceMatcher
    matcher = difflib.SequenceMatcher(None, gold_cleaned, whisper_cleaned)
    aligned_rows = []

    for tag, i1, i2, j1, j2 in matcher.get_opcodes():
        if tag in ('equal', 'replace'):
            # Words matched (or replaced). Write the original uncleaned words.
            length = max(i2 - i1, j2 - j1)
            for offset in range(length):
                g_word = gold_words[i1 + offset] if (i1 + offset) < i2 else ""
                w_word = whisper_words[j1 + offset] if (j1 + offset) < j2 else ""
                t_start = timestamps[j1 + offset][0] if (j1 + offset) < j2 else ""
                t_end = timestamps[j1 + offset][1] if (j1 + offset) < j2 else ""
                
                aligned_rows.append([g_word, w_word, t_start, t_end])
                
        elif tag == 'delete':
            # Word exists in Gold, but Whisper missed it (No timestamp)
            for g in range(i1, i2):
                aligned_rows.append([gold_words[g], "", "", ""])
                
        elif tag == 'insert':
            # Whisper hallucinated a word (Has timestamp, but no Gold word)
            for w in range(j1, j2):
                aligned_rows.append(["", whisper_words[w], timestamps[w][0], timestamps[w][1]])

    # 5. Save to CSV
    with open(out_path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow(['Gold_Word', 'Whisper_Word', 'Start_Time', 'End_Time'])
        writer.writerows(aligned_rows)


def main():
    """
    Main execution pipeline for Step 3.
    Iterates over all JSON files and creates aligned CSV reports.[cite: 5]
    """
    os.makedirs(DIR_OUT, exist_ok=True)
    
    # Add a check to ensure the input directory exists
    if not os.path.exists(DIR_JSON):
        print(f"ERROR: Cannot find JSON directory at {DIR_JSON}")
        print("Please run Step 2 first.")
        return

    json_files = [f for f in os.listdir(DIR_JSON) if f.endswith('.json')]
    print(f"Found {len(json_files)} JSON files to align.\n")
    
    for json_file in json_files:
        base_name = json_file.replace('.json', '')
        txt_file = base_name + '.txt'
        
        json_path = os.path.join(DIR_JSON, json_file)
        txt_path = os.path.join(DIR_TXT, txt_file)
        out_path = os.path.join(DIR_OUT, base_name + '_aligned.csv')

        if not os.path.exists(txt_path):
            print(f"WARNING - Skipping {json_file}: No matching TXT file found in {DIR_TXT}.")
            continue

        try:
            align_transcripts(json_path, txt_path, out_path)
            print(f"SUCCESS - Aligned: {base_name}.csv")
        except Exception as e:
            print(f"ERROR - Could not align {base_name}: {e}")

    print("\nAlignment pipeline finished.")


if __name__ == "__main__":
    main()